#!/usr/bin/env python3
"""Paper T — Results prose generated from summary.json + labels_report.json (no number typed by hand).
Usage: paperT_results_prose.py RES_DIR OUT.md"""
import os, sys, json, numpy as np
RES=sys.argv[1]; out=sys.argv[2]; S=json.load(open(os.path.join(RES,'summary.json'))); L=json.load(open(os.path.join(RES,'labels_report.json')))
T=['2018','2019','2020','2021','2022']; Y={t:S['years'][t] for t in T}; R=S['decision_rules']; B=S['B']
pct=lambda x,d=1: f"{100*x:.{d}f}%"
comp=[L[t]['share_known'] for t in T]; lifts=[Y[t]['asof']['gb_A']['0.01']['lift'] for t in T]; hl=[Y[t]['hindsight']['gb']['0.01']['lift'] for t in T]
ratios=[Y[t]['hindsight_optimism_ratio_gb'] for t in T]; rec=[Y[t]['asof']['gb_A']['0.01']['recall'] for t in T]; hrec=[Y[t]['hindsight']['gb']['0.01']['recall'] for t in T]
auc=[Y[t]['asof']['gb_A']['auc_roc'] for t in T]; hauc=[Y[t]['hindsight']['gb']['auc_roc'] for t in T]
recB=[Y[t]['asof']['gb_B']['0.01']['recall'] for t in T]; dr_p=[Y[t]['triage_1pct']['p']['dollar_recall'] for t in T]; dr_px=[Y[t]['triage_1pct']['p_x_payment']['dollar_recall'] for t in T]; dr_pay=[Y[t]['triage_1pct']['payment_only']['dollar_recall'] for t in T]
np_p=[Y[t]['triage_1pct']['p']['distinct_npis'] for t in T]; np_px=[Y[t]['triage_1pct']['p_x_payment']['distinct_npis'] for t in T]
alg=[Y[t]['allocation_1pct']['global_recall'] for t in T]; aly=[Y[t]['allocation_1pct']['yield_aware_recall'] for t in T]
r3=[Y[t]['asof_3yr']['gb_A']['0.01']['recall'] for t in T]; a3=[Y[t]['asof_3yr']['gb_A']['auc_roc'] for t in T]
P=[]
P.append(f"**Label completeness.** Of the {L['positives']:,} provider-years that are eventual positives in the {L['rows_kept']:,}-row panel, the share known at the start of the as-of year ranged from {pct(comp[0])} for t = 2018 to {pct(comp[-1])} for t = 2022 (Table 1): a model trained in January 2018 could see {L['2018']['train_known_positives']:,} of the {L['2018']['train_eventual_positives']:,} provider-years that would eventually be labelled positive in its training years, and one trained in January 2022 saw {L['2022']['train_known_positives']:,} of {L['2022']['train_eventual_positives']:,}. The remainder sat in the training data as negatives.")
P.append(f"**T1 — hindsight optimism (rule met in {R['T1']['years_met']}/5 years; {'MET' if R['T1']['met'] else 'NOT MET'}).** At a 1% review budget the as-of gradient-boosting model (variant A) reached {pct(min(rec))}–{pct(max(rec))} of the year's later-excluded provider-years (lift {min(lifts):.1f}–{max(lifts):.1f}), against {pct(min(hrec))}–{pct(max(hrec))} (lift {min(hl):.1f}–{max(hl):.1f}) for the companion study's cross-validated model scored on the same years with labels current at the study date. The hindsight-optimism ratio was {', '.join(f'{r:.2f}' for r in ratios)} for t = 2018–2022 (Figure 1); the as-of AUC-ROC was {min(auc):.3f}–{max(auc):.3f} against {min(hauc):.3f}–{max(hauc):.3f} in hindsight. Under the three-year label the as-of model's recall@1% was {pct(min(r3))}–{pct(max(r3))} and its AUC-ROC {min(a3):.3f}–{max(a3):.3f} (Table 2b).")
d2=R['T2']; P.append(f"**T2 — peer-normalised features (rule met in {d2['years_met']}/5 years; {'MET' if d2['met'] else 'NOT MET'}).** Normalising the 48 numeric features within calendar year and provider type (variant B) gave recall@1% of {pct(min(recB))}–{pct(max(recB))} against {pct(min(rec))}–{pct(max(rec))} for variant A; the five-year mean difference (B − A) was {d2['mean_diff']:+.4f} (95% bootstrap interval {d2['ci'][0]:+.4f} to {d2['ci'][1]:+.4f}, B = {B}).")
d3=R['T3']; P.append(f"**T3 — ranking by expected payments at risk (rule met in {d3['years_met']}/5 years; {'MET' if d3['met'] else 'NOT MET'}).** At the same 1% budget, ranking by score × Medicare payment reached {pct(min(dr_px))}–{pct(max(dr_px))} of the payments made to later-excluded provider-years, against {pct(min(dr_p))}–{pct(max(dr_p))} when ranking by score alone and {pct(min(dr_pay))}–{pct(max(dr_pay))} when ranking by payment alone; it reached {min(np_px):,}–{max(np_px):,} distinct later-excluded providers per year against {min(np_p):,}–{max(np_p):,} for the score ranking (Table 3).")
d4=R['T4']; P.append(f"**T4 — yield-aware allocation across provider types (rule met in {d4['years_met']}/5 years; {'MET' if d4['met'] else 'NOT MET'}).** Allocating the 1% budget across provider types in proportion to the previous year's yield gave recall@1% of {pct(min(aly))}–{pct(max(aly))} against {pct(min(alg))}–{pct(max(alg))} for the global ranking; five-year mean difference {d4['mean_diff']:+.4f} (95% bootstrap interval {d4['ci'][0]:+.4f} to {d4['ci'][1]:+.4f}).")
P.append(f"**Summary of the pre-specified rules.** T1 {'met' if R['T1']['met'] else 'not met'}; T2 {'met' if d2['met'] else 'not met'}; T3 {'met' if d3['met'] else 'not met'}; T4 {'met' if d4['met'] else 'not met'} (Table 4). The protocol's SHA-256 is {S['protocol_sha256']}.")
open(out,'w').write('\n\n'.join(P)+'\n'); print('\n\n'.join(P))
